import sys

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
cap = [int(x) for x in data[2:2 + n]]
thr = [int(x) for x in data[2 + n:2 + n + m]]

def feasible(k):
    slots = [(j, s) for j in range(m) for s in range(k)]
    match = [-1] * len(slots)

    def try_task(i, seen):
        for idx, (j, s) in enumerate(slots):
            if thr[j] >= cap[i] and not seen[idx]:
                seen[idx] = True
                if match[idx] == -1 or try_task(match[idx], seen):
                    match[idx] = i
                    return True
        return False

    for i in range(n):
        if not try_task(i, [False] * len(slots)):
            return False
    return True

if max(cap) > max(thr):
    print(-1)
else:
    k = 1
    while not feasible(k):
        k += 1
    print(2 * k - 1)

